Calcular las métrcias
Calcular las metricas que nos interesan.

tree_metrics &lt;- custom_metrics(resultados_prueba_tree,
  truth = PYALC,
  estimate = .pred_class
) |&gt;
  mutate(model = "Árbol")

Poner las métricas en un formato más fácil de comparar.

rbind(tree_metrics, lm_metrics) |&gt;
  pivot_wider(names_from = model, values_from = .estimate)

Tip






data(dataUMworkshop)
# The outcome variable is specified as a factor
the_data &lt;- dataUMworkshop |&gt;
  select(-outcome_count) |&gt;
  mutate(outcome = factor(outcome)) |&gt;
  rename(P200 = P2)





lm_results &lt;- lm_model |&gt;
  fit(outcome ~ ., data = the_data)

Here the model is fitted-estimated using the fit() function. The response variable (outcome) and the predictors (.) are specified and the the_data object is used as a database.

Añadir detalles a las tabla

datos_ley_moral  |&gt;
datos_organizados("Justificación de los juicios")  |&gt; 
tbl_summary(
    by = SITUACIONES,
    include=-c(ID, SEXO, EDAD))   |&gt; 
     modify_table_body(
    fun = ~ dplyr::arrange(.x, desc(readr::parse_number(stat_1)))
  )  |&gt;
    modify_header(
        label= "**Justificación de los juicios**"
    )

Exportar a tablas a word

tabla_gravedad_y_castigo &lt;- datos_ley_moral  |&gt; 
datos_organizados("Escalas gravedad y castigo")   |&gt; 
filter(SITUACIONES %in% c("Linchamiento", "Narcotráfico"))  |&gt; 
tbl_summary(
    by = SITUACIONES,
    include=-c(ID, SEXO, EDAD),
    type= list(`Escala de gravedad` ~ "continuous", 
    `Escala de castigo` ~ "continuous"), 
    statistic = all_continuous() ~ "{mean}, ({sd})")   |&gt; 
    add_p(test = list(
          all_continuous() ~ "paired.wilcox.test"),
        group = ID)    |&gt; 
        as_gt()

gt::gtsave(tabla_gravedad_y_castigo, "tabla_gravedad_y_castigo.docx")

