Tip



## Pro
transformar_respuesta &lt;- function(x) {
  case_when(
    x == "Muy mal" ~ 1,
    x == "Mal" ~ 2,
    x == "Notan mal" ~ 3,
    x == "Para nada mal" ~ 4,
    TRUE ~ NA
  )
}

los_datos |&gt; 
  select(AWRMAR, AWRALC, AWRCIG) |&gt; 
  mutate(across(everything(), transformar_respuesta)) |&gt; 
   mutate(TOTAL = (AWRMAR + AWRALC + AWRCIG)/3)

